def shl_athlete_career(
    athlete_uuid: str,
    master_site_instance_id: Optional[str] = None,
    *,
    return_parsed: bool = True,
    return_as_pandas: bool = False,
    **kwargs,
) -> Union[pl.DataFrame, pd.DataFrame, Dict, str]:
    """Player career totals by season.

    Endpoint: ``GET https://www.shl.se/api/statistics-v2/athlete/playerProfile_gameLog``
    Example URL: https://www.shl.se/api/statistics-v2/athlete/playerProfile_gameLog?playerUuid=qQ9-349c7WDv6&masterSiteInstanceId=shl1_shl

    Args:
        athlete_uuid: Required. Athlete uuid.
        master_site_instance_id: Site instance (shl1_shl). No effect in the drop-one probe.
        return_parsed: parse the payload through parse_shl_stats_info -> polars DataFrame (default True). Pass return_parsed=False for the raw JSON Dict.
        return_as_pandas: with return_parsed, return a pandas DataFrame instead of polars.
        **kwargs: Forwarded to the underlying HTTP getter.

    Returns:
        A polars/pandas DataFrame by default; the raw JSON ``Dict`` when ``return_parsed=False``.

    Raises:
        sportsdataverse.errors.NoDataError: SHL answered 404, an empty body (gameday routes before 2023/24), a table with no rows, another game / team / ssgt than the one asked for, or the season and game type are not in layout-info.
        ValueError: The host answered 400 / 422 -- the request is wrong; retrying cannot help.
        AssetFetchError: The fetch failed (a non-2xx answer or a connection failure after retries, e.g. 401/403/429/5xx, or an empty or unreadable 200 body) -- the answer is unknown, not empty.

    Example:
        Quick start::

            from sportsdataverse.hockey.shl import shl_athlete_career
            shl_athlete_career(athlete_uuid='qQ9-349c7WDv6', master_site_instance_id='shl1_shl')

        See Also:
            * `SHL`_ - the Swedish Hockey League site whose API this is
            * `fastRhockey`_ - the SportsDataverse hockey package for R

        .. _SHL: https://www.shl.se/
        .. _fastRhockey: https://fastRhockey.sportsdataverse.org
    """
    _caller_params = kwargs.pop("params", None) or {}
    _params = {
        "playerUuid": athlete_uuid,
        "masterSiteInstanceId": master_site_instance_id,
    }
    _params.update(_caller_params)
    raw = _get(
        "https://www.shl.se/api/statistics-v2/athlete/playerProfile_gameLog",
        params=_params,
        **kwargs,
    )
    if return_parsed:
        return parse_shl_stats_info(raw, return_as_pandas=return_as_pandas, columns=_PARSER_COLUMNS["athlete_career"])
    return raw


