def shl_stats_info(
    module: str,
    season: int,
    game_type: Optional[str] = "regular",
    *,
    return_parsed: bool = True,
    return_as_pandas: bool = False,
    **kwargs,
) -> Union[pl.DataFrame, pd.DataFrame, Dict, str]:
    """Stats table of one module for an ssgt (standings, players, goalies, teams, games).

    Endpoint: ``GET https://www.shl.se/api/statistics-v2/stats-info/{module}``
    Example URL: https://www.shl.se/api/statistics-v2/stats-info/players_summary?count=1000&season=2026&gameType=regular

    Args:
        module: Stats module: <group>_<table>. Every name under layout-info [].filters.<group>.modules.
        season: Required. Season END year (2026 = 2025/26). Mapped to the provider's ssgt through /statistics-v2/layout-info (SHL 1975/76 on); a season it does not list raises NoDataError.
        game_type: Game type: regular (Grundserie), playoff (Slutspel), qualdown (relegation qualification) or playin (2023/24 on).
        return_parsed: parse the payload through parse_shl_stats_info -> polars DataFrame (default True). Pass return_parsed=False for the raw JSON Dict.
        return_as_pandas: with return_parsed, return a pandas DataFrame instead of polars.
        **kwargs: Forwarded to the underlying HTTP getter.

    Returns:
        A polars/pandas DataFrame by default; the raw JSON ``Dict`` when ``return_parsed=False``.

    Raises:
        sportsdataverse.errors.NoDataError: SHL answered 404, an empty body (gameday routes before 2023/24), a table with no rows, another game / team / ssgt than the one asked for, or the season and game type are not in layout-info.
        ValueError: The host answered 400 / 422 -- the request is wrong; retrying cannot help.
        AssetFetchError: The fetch failed (a non-2xx answer or a connection failure after retries, e.g. 401/403/429/5xx, or an empty or unreadable 200 body) -- the answer is unknown, not empty.

    Example:
        Quick start::

            from sportsdataverse.hockey.shl import shl_stats_info
            shl_stats_info(module='players_summary', season=2026)

        See Also:
            * `SHL`_ - the Swedish Hockey League site whose API this is
            * `fastRhockey`_ - the SportsDataverse hockey package for R

        .. _SHL: https://www.shl.se/
        .. _fastRhockey: https://fastRhockey.sportsdataverse.org
    """
    if module not in (
        "players_summary",
        "players_point",
        "players_strength",
        "players_goal",
        "players_timeOnIce",
        "players_powerplay",
        "players_penaltykilling",
        "players_equalStrength",
        "players_penalty",
        "players_plusMinus",
        "players_faceoff",
        "players_shot",
        "players_defensive",
        "players_penaltyShot",
        "players_extendedMetrics",
        "teams_result",
        "teams_goal",
        "teams_powerplay",
        "teams_penaltyKilling",
        "teams_attendance",
        "teams_penalty",
        "teams_shotsForward",
        "teams_shotsAgainst",
        "teams_faceoff",
        "teams_penaltyShot",
        "teams_extendedMetrics",
        "teams_stoppage",
        "goalkeepers_summary",
        "goalkeepers_shotAgainst",
        "goalkeepers_result",
        "goalkeepers_strength",
        "goalkeepers_penaltyShot",
        "games_games",
        "standings_standings",
    ):
        raise ValueError(
            f"module must be one of ('players_summary', 'players_point', 'players_strength', 'players_goal', 'players_timeOnIce', 'players_powerplay', 'players_penaltykilling', 'players_equalStrength', 'players_penalty', 'players_plusMinus', 'players_faceoff', 'players_shot', 'players_defensive', 'players_penaltyShot', 'players_extendedMetrics', 'teams_result', 'teams_goal', 'teams_powerplay', 'teams_penaltyKilling', 'teams_attendance', 'teams_penalty', 'teams_shotsForward', 'teams_shotsAgainst', 'teams_faceoff', 'teams_penaltyShot', 'teams_extendedMetrics', 'teams_stoppage', 'goalkeepers_summary', 'goalkeepers_shotAgainst', 'goalkeepers_result', 'goalkeepers_strength', 'goalkeepers_penaltyShot', 'games_games', 'standings_standings'); got {module!r}"
        )
    if game_type not in ("regular", "playoff", "qualdown", "playin"):
        raise ValueError(f"game_type must be one of ('regular', 'playoff', 'qualdown', 'playin'); got {game_type!r}")
    _caller_params = kwargs.pop("params", None) or {}
    _params = {
        "count": 1000,
        "season": season,
        "gameType": game_type,
    }
    _params.update(_caller_params)
    raw = _get(
        f"https://www.shl.se/api/statistics-v2/stats-info/{module}",
        params=_params,
        **kwargs,
    )
    if return_parsed:
        return parse_shl_stats_info(raw, return_as_pandas=return_as_pandas, columns=_PARSER_COLUMNS["stats_info"])
    return raw


